
(()=>{'use strict';
const DEFAULT=[
 {title:'3D-Produktkonfigurator',eyebrow:'CASE 01 / DIGITAL PRODUCT EXPERIENCE',headline:'Vom Produkt zur qualifizierten Anfrage.',description:'Konzeption und Aufbau eines eigenen B2B2C-3D-Produktkonfigurators mit Anbindung an ERP und Fertigung. Der Konfigurator macht komplexe Produkte digital erlebbar und unterstützt die Leadgenerierung.',stats:[['250+','Leads pro Monat']],tags:['B2B2C','3D-Konfigurator','ERP-Anbindung','Leadgenerierung'],visual:'config'},
 {title:'Digital Sales & Commerce',eyebrow:'CASE 02 / COMMERCIAL IMPACT',headline:'Digitale Vertriebskanäle messbar weiterentwickeln.',description:'Mitwirkung an der Weiterentwicklung des digitalen Vertriebs, der Customer Journey und der E-Commerce-Plattformen. Im Zeitraum von drei Jahren stieg der Online-Umsatz von unter 5 Mio. € auf über 10 Mio. €; dieser Anstieg war eine Teamleistung, zu der ich wesentlich beigetragen habe.',stats:[['< 5 Mio. €','Online-Umsatz zu Beginn'],['> 10 Mio. €','Online-Umsatz nach 3 Jahren']],tags:['E-Commerce','Conversion','Tracking','Customer Journey'],visual:'growth'},
 {title:'Internationale Plattformlandschaft',eyebrow:'CASE 03 / SCALE & SYSTEMS',headline:'Ein digitales Fundament für internationale Märkte.',description:'Zusammenarbeit mit internationalen Tochtergesellschaften und Vertriebspartnern sowie Weiterentwicklung der digitalen Plattformlandschaft. Schwerpunkte waren unter anderem Headless B2B Commerce, Dateninfrastruktur und Salesforce-Einführung.',stats:[['13','Internationale Tochtergesellschaften'],['3','Exklusive Vertriebspartner']],tags:['Headless Commerce','Salesforce','Internationalisierung','Daten'],visual:'flow'}
];
const publicExport=JSON.parse(document.getElementById('published-config').textContent||'{}').publicExport===true;const KEY='beyondcv_cases_v1';let cases;try{const stored=JSON.parse(localStorage.getItem(KEY)||'null');cases=Array.isArray(window.__BEYOND_PUBLISHED_CASES__)&&window.__BEYOND_PUBLISHED_CASES__.length===3?structuredClone(window.__BEYOND_PUBLISHED_CASES__):Array.isArray(stored)&&stored.length===3?stored:structuredClone(DEFAULT)}catch{cases=structuredClone(DEFAULT)}
let current=0,glass='clear',posts=true,rail=true,editing=false;
const esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function visual(c){if(c.visual==='config')return `<h4>INTERAKTIVE PRODUKTVORSCHAU · KONZEPTVISUALISIERUNG</h4><div class="p5-railing ${posts?'':'nopost'} ${rail?'':'norail'}"><div class="deck"></div><div class="glass ${glass==='frosted'?'frosted':glass==='smoke'?'smoke':''}"></div><div class="posts"><i></i><i></i><i></i><i></i></div><div class="rail"></div></div><div class="p5-controls"><button data-glass="clear" class="${glass==='clear'?'on':''}">Klarsicht</button><button data-glass="frosted" class="${glass==='frosted'?'on':''}">Mattglas</button><button data-glass="smoke" class="${glass==='smoke'?'on':''}">Rauchglas</button><button id="p5posts" class="${posts?'on':''}">Pfosten ${posts?'an':'aus'}</button><button id="p5rail" class="${rail?'on':''}">Handlauf ${rail?'an':'aus'}</button></div><div class="p5-note">Illustrative, frei gestaltete Vorschau – keine maßstabsgetreue Darstellung oder echte Anbindung an das ursprüngliche Konfiguratorsystem.</div>`;
if(c.visual==='growth')return `<h4>UMSATZENTWICKLUNG · NUR BELEGTE ENDWERTE</h4><div class="p5-bars"><div><b class="bar" style="height:37%"></b><small>Beginn: &lt; 5 Mio. €</small></div><div><b class="bar" style="height:88%"></b><small>Nach 3 Jahren: &gt; 10 Mio. €</small></div></div><div class="p5-note">Schematische Darstellung der Größenordnung. Keine erfundenen Zwischenjahre; der Umsatzanstieg ist keine alleinige persönliche Leistung.</div>`;
return `<h4>PLATTFORMEN & MÄRKTE · SCHEMATISCH</h4><div class="p5-flow"><span>Digitale Kanäle</span><b>→</b><span>Headless B2B</span><b>↔</b><span>ERP / Daten</span><b>→</b><span>Internationale Märkte</span></div><div class="p5-note">Konzeptionelle Übersicht der Themenfelder, kein technischer Ist-Architekturplan.</div>`}
function open(i=0){current=i;editing=false;render()}
function close(){const el=document.getElementById('p5-root');if(el)el.remove()}
function render(){const c=cases[current];let root=document.getElementById('p5-root');if(!root){root=document.createElement('div');root.id='p5-root';root.className='p5';document.querySelector('main.main').append(root)}root.innerHTML=`<div class="p5-shell"><div class="p5-top"><div><span class="p5-kicker">BEYOND THE CV / SELECTED WORK</span><h2>Impact, den man erkunden kann.</h2><p class="p5-sub">Drei ausgewählte Projekte und Wirkungsschwerpunkte. Interaktive Darstellungen machen die dahinterliegenden Ideen greifbar.</p></div><button class="p5-close" id="p5close" aria-label="Projektwelt schließen">✕ Schließen</button></div><div class="p5-tabs">${cases.map((x,i)=>`<button data-case="${i}" class="${i===current?'selected':''}">0${i+1} · ${esc(x.title)}</button>`).join('')}</div><div class="p5-main"><section class="p5-info"><span class="p5-kicker">${esc(c.eyebrow)}</span><h3>${esc(c.headline)}</h3><p>${esc(c.description)}</p><div class="p5-stats">${c.stats.map(a=>`<div class="p5-stat"><b>${esc(a[0])}</b><small>${esc(a[1])}</small></div>`).join('')}</div><div class="p5-tags">${c.tags.map(t=>`<span>${esc(t)}</span>`).join('')}</div></section><section class="p5-visual">${visual(c)}</section></div><div class="p5-bottom"><span>INTERACTIVE CASE STUDIES · PHASE 05</span>${publicExport?'':`<button class="p5-edit" id="p5edit">${editing?'Editor schließen':'Inhalte bearbeiten ✎'}</button>`}</div>${editing?`<div class="p5-editor"><label>Projekttitel<input id="p5title" value="${esc(c.title)}"></label><label>Headline<input id="p5headline" value="${esc(c.headline)}"></label><label>Beschreibung<textarea id="p5desc">${esc(c.description)}</textarea></label><label>Schlagworte (durch Komma getrennt)<input id="p5tags" value="${esc(c.tags.join(', '))}"></label><div class="p5-editor-actions"><button id="p5save">Speichern</button><button id="p5reset">Dieses Projekt zurücksetzen</button></div><p class="p5-note">Änderungen werden nur in diesem Browser gespeichert. Zahlen und Fakten bitte nur mit überprüften Angaben ändern.</p></div>`:''}</div>`;
root.querySelector('#p5close').onclick=close;root.querySelectorAll('[data-case]').forEach(b=>b.onclick=()=>open(+b.dataset.case));root.querySelectorAll('[data-glass]').forEach(b=>b.onclick=()=>{glass=b.dataset.glass;render()});const pb=root.querySelector('#p5posts');if(pb)pb.onclick=()=>{posts=!posts;render()};const rb=root.querySelector('#p5rail');if(rb)rb.onclick=()=>{rail=!rail;render()};if(!publicExport)root.querySelector('#p5edit').onclick=()=>{editing=!editing;render()};if(editing){root.querySelector('#p5save').onclick=()=>{c.title=root.querySelector('#p5title').value.trim();c.headline=root.querySelector('#p5headline').value.trim();c.description=root.querySelector('#p5desc').value.trim();c.tags=root.querySelector('#p5tags').value.split(',').map(x=>x.trim()).filter(Boolean);try{localStorage.setItem(KEY,JSON.stringify(cases))}catch(e){alert('Speichern fehlgeschlagen: '+e.message)}editing=false;render()};root.querySelector('#p5reset').onclick=()=>{cases[current]=structuredClone(DEFAULT[current]);localStorage.setItem(KEY,JSON.stringify(cases));editing=false;render()}}}
const nav=document.querySelector('.top nav');if(nav){const b=document.createElement('button');b.id='projectsBtn';b.textContent='PROJEKTE';b.onclick=()=>open();nav.insertBefore(b,document.getElementById('careerBtn'))}
// Add a project entry point to the existing fourth world without changing the original engine.
const layer=document.getElementById('layer');if(layer){new MutationObserver(()=>{const panel=layer.querySelector('.panel');if(!panel||!panel.textContent.includes('PROJEKTE')&&!panel.textContent.includes('Projekte'))return;if(panel.querySelector('#p5world'))return;const footer=panel.querySelector('.world-footer');if(footer){const b=document.createElement('button');b.id='p5world';b.className='primary';b.textContent='Interaktive Projekte entdecken ↗';b.onclick=()=>open();footer.prepend(b)}}).observe(layer,{childList:true})}
document.addEventListener('keydown',e=>{if(e.key==='Escape'&&document.getElementById('p5-root'))close()});
})();
